  const total = phases.reduce((n, p) => n + p.tasks.length, 0), complete = Object.values(checks).filter(Boolean).length, percent = Math.round((complete / total) * 100), data = unwrap(current.data), run = latestRun(data), activeSource = source || data?.sources?.[0], list = cases.data?.payload?.cases || (Array.isArray(cases.data?.payload) ? cases.data.payload : [])
