function Dashboard({ health, percent, complete, total, openCases, openPlan, openWorkspace, openRender, renderStatus }) { const [expanded, setExpanded] = useState(null); const h = health.data?.payload || {}, online = health.isSuccess && h?.status === 'ok', pipeline = h?.pipeline_build || {}, speech = h?.speech_runtime || {}, transcription = speech.transcription || {}, pipelineState = pipeline.total === 21 ? `${pipeline.implemented_foundations || 0}/21` : '—'; const items=[['API',health.isPending?'CHECKING':online?'ONLINE':'CHECK',API_BASE,online?'healthy':'warning'],['Runtime',h?.runtime_self_test==='passed'?'PASSED':'CHECK',h?.source_revision?.slice?.(0,12)||'source revision',h?.runtime_self_test==='passed'?'healthy':'warning'],['Pipeline',pipelineState,`${pipeline.queued||0} queued · ${pipeline.conditional_or_not_invoked||0} conditional`,pipeline.total===21?'healthy':'warning'],['Transcription',transcription.configured_provider==='faster_whisper'?(transcription.adapter_installed?'WIRED':'CONFIGURED'):'OFF',transcription.adapter_installed?'faster-whisper is installed in the advertised runtime; real Render execution must still be verified':'faster-whisper is not installed in the current runtime','warning']]; return <div className="vv-dashboard"><PageTitle eyebrow="BUILD CONTROL" title="Developer Overview" action={<div className="vv-dashboard-title-actions"><span className="vv-version-chip">v0.2.37 · API 0.2.27</span><Button variant="secondary" onClick={() => health.refetch()}><RefreshCw size={14}/> Refresh</Button></div>}/><section className="vv-dashboard-status-panel" aria-label="Current system state"><div className="vv-dashboard-status-heading"><div><div className="vv-eyebrow">CURRENT SYSTEM STATE</div><h2>Live runtime at a glance</h2></div><span>Tap a row to inspect</span></div><div className="vv-dashboard-status-list">{items.map(([label,value,detail,state])=><Metric key={label} label={label} value={value} detail={detail} state={state} expanded={expanded===label} onToggle={()=>setExpanded(value=>value===label?null:label)}/>)}</div></section><div className="vv-dashboard-next-grid"><section className="vv-panel vv-dashboard-next"><div className="vv-panel-head"><h2>Next Engineering Move</h2><span>transcription first</span></div><p className="vv-copy">Create a real case, upload a short known WAV, run the repaired transcription path, and verify the timestamped transcript is persisted.</p><div className="vv-dashboard-actions"><Button variant="accent" onClick={openCases}><ClipboardList size={15}/> Case Workbench</Button><Button variant="secondary" onClick={openRender}><Server size={15}/> Render Runtime</Button></div></section><details className="vv-panel vv-dashboard-details"><summary><span><span className="vv-eyebrow">RUNTIME FINGERPRINT</span><strong>/health</strong></span><ChevronDown size={16}/></summary><pre className="vv-code">{JSON.stringify(h, null, 2)}</pre></details></div><section className="vv-panel vv-dashboard-activity"><div className="vv-panel-head"><h2>Engineering Activity</h2><span>source-backed state</span></div><div className="vv-data-grid"><Data label="MVP board" value={`${percent}% complete`}/><Data label="Checks" value={`${complete} of ${total}`}/><Data label="Transcription" value={transcription.configured_provider==='faster_whisper'?(transcription.adapter_installed?'Wired · unverified':'Configured · package missing'):'Not configured'}/><Data label="Render service" value="Open Render Runtime"/></div></section><section className="vv-panel vv-dashboard-links"><div className="vv-panel-head"><h2>Canonical Links</h2><span>repository</span></div><div className="grid gap-2 sm:grid-cols-3"><DocLink title="Methodology" href={DOCS.methodology} detail="Analysis methods"/><DocLink title="Pipeline" href={DOCS.pipeline} detail="Canonical 21 stage pipeline"/><DocLink title="Architecture" href={DOCS.architecture} detail="System boundaries"/></div></section></div> }
function CaseWorkbench({ list, selectedCaseId, setSelectedCaseId, title, setTitle, create, file, setFile, upload, progress, uploadStage, source, data, playback, playbackUrl, analyze, run, renderProgress, error, refresh, openWorkspace, notify, openState, toggleState }) { const canAnalyze = Boolean(selectedCaseId && source?.source_id && !analyze.isPending); const workflowStep = !selectedCaseId ? 1 : !source?.source_id ? 2 : 3; const onFileChange = event => { const selected = event.target.files?.[0] || null; setProgress(0); setFile(selected); if (!selected) return; if (!supportedAudioFile(selected)) { setFile(null); event.target.value=''; notify('error','Unsupported Recording','Choose WAV, MP3, M4A, MP4, AAC, OGG, WebM, or FLAC audio.'); } else if (selected.size <= 0) { setFile(null); event.target.value=''; notify('error','Empty Recording','The selected audio file contains no data.'); } }; const handleUpload = () => { const selectedFile = file || document.getElementById('audio-file')?.files?.[0] || null; if (!selectedFile) { notify('warning','Choose Recording','Select a recording before uploading it to this case.'); return } if (!supportedAudioFile(selectedFile)) { notify('error','Unsupported Recording','Choose WAV, MP3, M4A, MP4, AAC, OGG, WebM, or FLAC audio.'); return } if (selectedFile.size <= 0) { notify('error','Empty Recording','The selected audio file contains no data.'); return } setFile(selectedFile); upload.mutate({ uploadFile: selectedFile }); }; const activeLabel = uploadStage === 'converting' ? `Converting ${Math.round(progress)}%` : uploadStage === 'processing' ? 'Processing…' : `Uploading ${Math.round(progress)}%`; const section = (id,titleText,eyebrow,children) => { const open=openState.has(id); return <section className={`vv-panel mb-4 vv-workflow-card ${open?'':'is-collapsed'} ${id==='analysis'&&analyze.isPending?'vv-workflow-active':''}`}><div className="vv-panel-head"><div className="flex min-w-0 items-center gap-2"><button type="button" className="vv-collapse-button" onClick={()=>toggleState(id)} aria-expanded={open} aria-label={`${open?'Collapse':'Expand'} ${titleText}`}><ChevronDown size={15} className={`transition-transform ${open?'':'-rotate-90'}`}/></button><div className="min-w-0"><div className="vv-eyebrow">{eyebrow}</div><h2 className="truncate">{titleText}</h2></div></div><span>{open ? '' : 'Collapsed'}</span></div>{open&&<div className="vv-collapsed-content mt-4">{children}</div>}</section> }
  return <div><PageTitle eyebrow="CASE WORKBENCH" title="Build a Real Analysis Case" action={<div className="flex gap-2"><Button variant="secondary" onClick={refresh}><RefreshCw size={14}/> Refresh</Button><Button variant="secondary" onClick={()=>{const all=new Set(['case','upload','analysis']); const none=openState.size===3; ['case','upload','analysis'].forEach(id=>{if(none&&!openState.has(id)) toggleState(id)}); if(!none) ['case','upload','analysis'].filter(id=>openState.has(id)).forEach(id=>toggleState(id))}}>{openState.size===3?'Collapse All':'Expand All'}</Button></div>}/><section className="mb-4 border border-[var(--vv-border)] bg-[var(--vv-surface)] px-4 py-3 sm:px-5" aria-label="Case workflow"><div className="mb-2 text-[10px] font-bold uppercase tracking-[.16em] text-[var(--vv-muted)]">Case Workflow</div><div className="grid grid-cols-3 gap-2">{[[1,'Create Case','Define the case'],[2,'Upload Recording','Add audio source'],[3,'Analyze','Open evidence workspace']].map(([number,label,detail]) => <div key={number} className={`min-w-0 border-t-2 px-1 pt-2 ${workflowStep===number?'border-white text-white':workflowStep>number?'border-emerald-400/70 text-white/70':'border-white/10 text-white/35'}`} aria-current={workflowStep===number?'step':undefined}><div className="text-[11px] font-semibold">{number}. {label}</div><div className="mt-0.5 text-[10px] text-white/50">{detail}</div></div>)}</div><div className="mt-3 flex items-center gap-2 text-xs text-white/55"><span className="h-1.5 w-1.5 rounded-full bg-white" aria-hidden="true"/> Next: <strong className="text-white">{!selectedCaseId?'Create a case':!file?'Choose a recording':!source?.source_id?'Upload the recording':'Run analysis'}</strong></div></section>
    {section('case','Analysis Case','STEP 01',<><div className="grid min-w-0 gap-3 md:grid-cols-[minmax(0,1fr)_auto]"><div className="min-w-0"><label className="vv-field-label" htmlFor="case-title">New Case Title</label><input id="case-title" className="vv-input w-full min-w-0 max-w-full" value={title} onChange={e=>setTitle(e.target.value)} placeholder="Interview analysis"/></div><Button variant="accent" className="w-full self-end md:w-auto" onClick={()=>create.mutate()} disabled={create.isPending || !title.trim()}><CircleCheck size={15}/>{create.isPending?'Creating…':'Create Case'}</Button></div><div className="mt-4 min-w-0"><label className="vv-field-label" htmlFor="case-select">Existing Cases</label><select id="case-select" className="vv-input w-full min-w-0 max-w-full" value={selectedCaseId} onChange={e=>setSelectedCaseId(e.target.value)}><option value="">Select a case</option>{list.map(item=><option key={item.case_id} value={item.case_id}>{item.title||'Untitled case'} · {item.case_id?.slice(0,8)}</option>)}</select></div>{data?.case_id&&<div className="mt-4 flex min-w-0 items-center gap-3 vv-status-row"><CheckCircle2 size={15}/><span className="min-w-0 flex-1 truncate">{data.title||data.case_id}</span><span className="shrink-0 text-xs text-white/55">{STATUS_LABELS[data.status]||data.status||'Created'}</span></div>}</>)}
    {section('upload','File Upload','STEP 02',<><div className="grid min-w-0 gap-4 md:grid-cols-[minmax(0,1fr)_auto]"><div className="min-w-0"><label className="vv-field-label" htmlFor="audio-file">Recording</label><input id="audio-file" className="vv-input block w-full min-w-0 max-w-full" type="file" accept=".wav,.mp3,.m4a,.mp4,.aac,.ogg,.oga,.webm,.flac,audio/*" onChange={onFileChange} disabled={!selectedCaseId || upload.isPending}/>{file&&<p className="vv-copy mt-2 break-words">{file.name} · {(file.size/1024/1024).toFixed(2)} MB</p>}<p className="mt-2 text-[11px] text-[var(--vv-muted)]">Accepted: WAV, MP3, M4A, MP4, AAC, OGG, WebM, FLAC · converted to PCM WAV before analysis · up to 250 MB</p></div><Button variant="accent" className="w-full self-end md:w-auto md:min-w-[150px]" onClick={handleUpload} disabled={!selectedCaseId || upload.isPending}>{upload.isPending?activeLabel:'Upload Source'}</Button></div>{file&&<AudioUploadPlayer file={file} uploadProgress={progress} uploading={upload.isPending&&uploadStage!=='processing'} processing={upload.isPending&&uploadStage==='processing'} uploadComplete={Boolean(source?.source_id)} onStop={()=>{}}/>}{upload.isPending&&<div className="mt-4 vv-upload-state"><div className="vv-upload-top"><span>{uploadStage==='converting'?'Converting to PCM WAV':uploadStage==='processing'?'Server Processing':'Uploading PCM WAV'}</span><strong>{Math.round(progress)}%</strong></div><div className="vv-upload-track"><div className={`vv-upload-fill ${progress>=100?'complete':''}`} style={{width:`${Math.max(2,progress)}%`}}/></div><div className="vv-upload-status-line">{uploadStage==='processing'?'The API is validating the persisted source.':'Browser upload progress is measured from the actual file stream.'}</div></div>}{source&&<div className="vv-data-grid mt-4"><Data label="Source" value={source.source_id?.slice(0,12)}/><Data label="SHA-256" value={source.sha256?.slice(0,16)}/><Data label="Sample Rate" value={source.sample_rate?`${source.sample_rate} Hz`:'—'}/><Data label="Duration" value={source.duration_seconds?`${source.duration_seconds.toFixed(2)} s`:'—'}/></div>}</>)}
    {section('analysis','Playback + Analysis','STEP 03',<><div className="flex flex-wrap gap-2"><Button variant="secondary" onClick={()=>playback.mutate()} disabled={!source?.source_id||playback.isPending}><Play size={15}/>{playback.isPending?'Preparing…':'Open Secure Playback'}</Button><Button variant="accent" className={`${canAnalyze&&!run?'vv-workflow-action':''}`} onClick={()=>analyze.mutate()} disabled={!canAnalyze}>{analyze.isPending?'Running Canonical Pipeline…':'Run Analysis'}</Button><Button variant="secondary" onClick={openWorkspace} disabled={!selectedCaseId}><Waves size={15}/> Open Analysis Workspace</Button></div>{analyze.isPending||run&&run.status==='running'?<LiveRunProgress run={run} percent={renderProgress}/>:null}{playbackUrl&&<audio className="mt-4 w-full" controls src={playbackUrl}/>} {run&&<RunState run={run}/>}</>)}
    {error&&<section className="vv-panel"><div className="vv-status-row error"><XCircle size={16}/><span>{error}</span></div></section>}</div> }
function LiveRunProgress({ run, percent }) { const stages=run?.stages||[], active=stages.find(stage=>['running','processing','in_progress'].includes(stage.status)); const completed=stages.filter(stage=>['complete','completed','success','succeeded'].includes(stage.status)).length; const target=Math.max(percent, Math.round((completed/21)*100)); return <div className="vv-run-progress" aria-live="polite"><div className="vv-analysis-state-head"><span><span className="vv-render-dot live"/> Live analysis workflow</span><strong>{active?.name||run?.current_stage?.name||'Canonical analysis engine'} · {target}%</strong></div><div className="vv-run-progress-track"><div className={`vv-run-progress-fill ${active||run?.status==='running'?'running':''}`} style={{width:`${Math.max(3,target)}%`}}/></div><div className="vv-upload-status-line">{completed} of 21 workflow stages currently reported complete. Stage progress reflects persisted runtime lifecycle state.</div></div> }
function FileInfo() { const [open,setOpen]=useState(false); return <div className="relative"><button type="button" aria-label="Show compatible recording information" aria-expanded={open} onClick={()=>setOpen(value=>!value)} className="inline-flex h-6 w-6 items-center justify-center rounded-full border border-white/15 text-white/55 transition hover:border-white/30 hover:text-white"><Info size={14}/></button>{open&&<div className="absolute left-0 top-8 z-40 w-[min(350px,calc(100vw-3rem))] border border-white/10 bg-[#111]/98 p-4 text-xs text-white/65 shadow-[0_20px_50px_rgba(0,0,0,.45)] backdrop-blur-xl"><div className="font-semibold text-white">Compatible Recordings</div><p className="mt-2 leading-5">VoxVector accepts WAV, MP3, M4A, MP4, AAC, OGG, WebM, and FLAC audio. Non-WAV recordings are converted in your browser to 48 kHz mono 16-bit PCM WAV before secure upload. Maximum source file size is 250 MB.</p></div>}</div> }
function RunState({ run }) { const stages=run.stages||run.stage_states||[], build=run.pipeline_build||{}, testing=run.testing||{}; return <div className="mt-5"><div className="vv-panel-head"><h3>Pipeline Run</h3><span>{STATUS_LABELS[String(run.status||'').toLowerCase()]||run.status||'Unknown'}</span></div><div className="vv-data-grid"><Data label="Run" value={run.run_id?.slice(0,12)}/><Data label="Request" value={run.request_id?.slice(0,12)}/><Data label="Pipeline" value={run.pipeline_version}/><Data label="Stages complete" value={`${build.completed??stages.filter(stage=>['complete','completed','success','succeeded'].includes(stage.status)).length}/21`}/><Data label="Queued" value={build.pending??'—'}/><Data label="Not run" value={build.not_run??'—'}/><Data label="Failed" value={build.failed??0}/><Data label="QA state" value={testing?.current_commit_qa||'External workflow'}/></div>{testing?.historical_backend_baseline&&<p className="vv-copy mt-3">Historical backend baseline: {testing.historical_backend_baseline.passed} passed in {testing.historical_backend_baseline.duration_seconds}s. This is a baseline reference, not a current test result.</p>}{stages.length>0&&<div className="mt-4 space-y-1">{stages.map(stage=>{const status=stage.status||'pending',done=['complete','completed','success','succeeded'].includes(status),failed=['failed','error'].includes(status),running=['running','processing','in_progress'].includes(status);return <div className={`vv-status-row ${running?'vv-stage-live':''}`} key={stage.stage_id||stage.id}><span>{failed?<XCircle size={14}/>:done?<CheckCircle2 size={14}/>:running?<span className="vv-stage-status"><span className="running-dot"/> Running</span>:<Circle size={14}/>}</span><span>{stage.number?`${stage.number}. `:''}{stage.name||stage.stage_id||stage.id}</span><span className="ml-auto text-xs"><span className="vv-stage-status">{STATUS_LABELS[status]||status}</span>{stage.duration_ms!=null&&<span className="ml-2 text-white/35">{Math.round(stage.duration_ms)} ms</span>}</span></div>})}</div>}</div> }
function CaseHistory({ cases, selectedCaseId, loading, error, onRefresh, onOpen }) { return <div><PageTitle eyebrow="CASE ARCHIVE" title="Case History" action={<Button variant="secondary" onClick={onRefresh}><RefreshCw size={14}/> Refresh</Button>}/><section className="vv-panel mb-4"><div className="vv-panel-head"><h2>Saved Analysis Cases</h2><span>{cases.length} case{cases.length===1?'':'s'}</span></div><p className="vv-copy">Cases are persisted in the authenticated case store and can be reopened for later review. Selecting a case does not create a new analysis run.</p></section>{loading?<section className="vv-panel"><p className="vv-copy">Loading saved cases…</p></section>:error?<section className="vv-panel"><div className="vv-status-row error"><XCircle size={16}/><span>{error.message}</span></div></section>:cases.length?<div className="vv-history-list">{cases.map(item=>{const run=latestRun(item),source=item.sources?.[0];return <button type="button" className={`vv-history-item ${selectedCaseId===item.case_id?'active':''}`} key={item.case_id} onClick={()=>onOpen(item.case_id)}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="truncate text-sm font-semibold">{item.title||'Untitled analysis'}</div><div className="mt-1 truncate text-[10px] text-[var(--vv-muted)]">{item.case_id}</div></div><span className="shrink-0 text-[10px] text-white/45">{STATUS_LABELS[String(item.status||'').toLowerCase()]||item.status||'Created'}</span></div><div className="vv-history-meta"><span>Updated {item.updated_at?new Date(item.updated_at).toLocaleString():'—'}</span><span>{item.sources?.length||0} source{item.sources?.length===1?'':'s'}</span>{run&&<span>Run {run.run_id?.slice(0,10)} · {STATUS_LABELS[String(run.status||'').toLowerCase()]||run.status}</span>}{source&&<span>{source.duration_seconds?`${Number(source.duration_seconds).toFixed(1)} s`:''}</span>}</div></button>})}</div>:<section className="vv-panel"><p className="vv-copy">No saved cases yet. Create the first case from Case Workbench.</p></section>}</div> }
function RenderPanel({ statusQuery, logsQuery, deployMutation }) {
  const data=statusQuery.data?.payload||{}
  const service=(data.service&&typeof data.service==='object'?data.service:{})
  const deploy=(data.latest_deploy&&typeof data.latest_deploy==='object'?data.latest_deploy:{})
  const logRecords=Array.isArray(logsQuery.data?.payload?.logs)?logsQuery.data.payload.logs:Array.isArray(logsQuery.data?.payload?.events)?logsQuery.data.payload.events:[]
  const serviceState=service.suspended===true?'Suspended':service.state||service.status||'Active'
  return <div><PageTitle eyebrow="INFRASTRUCTURE" title="Render Runtime" action={<div className="flex flex-wrap gap-2"><Button variant="accent" onClick={()=>deployMutation.mutate()} disabled={deployMutation.isPending}><Play size={14}/>{deployMutation.isPending?'Deploying…':'Deploy Now'}</Button><Button variant="secondary" onClick={()=>{statusQuery.refetch();logsQuery.refetch()}}><RefreshCw size={14}/> Refresh</Button></div>}/>{deployMutation.isError&&<div className="vv-status-row error mb-4"><XCircle size={16}/><span>{displayText(deployMutation.error?.message,'Render deploy trigger failed.')}</span></div>}{deployMutation.isSuccess&&<div className="vv-status-row success mb-4"><CheckCircle2 size={16}/><span>Deploy request accepted. Render is responsible for the build and rollout lifecycle.</span></div>}<section className="vv-panel vv-live-render-card"><div className="vv-panel-head"><h2>Render API Connection</h2><span className="vv-render-state"><span className={`vv-render-dot ${statusQuery.isSuccess?'live':statusQuery.isError?'error':''}`}/>{statusQuery.isSuccess?'Connected':'Unavailable'}</span></div>{statusQuery.isPending?<p className="vv-copy">Querying the configured Render service…</p>:statusQuery.isError?<div className="vv-status-row error"><XCircle size={16}/><span>{displayText(statusQuery.error?.message,'Render API connection failed.')}</span></div>:<><div className="vv-render-grid"><div className="vv-render-value"><div className="vv-eyebrow">Service</div><strong>{displayText(service.name)}</strong><div className="mt-1 text-[10px] text-[var(--vv-muted)]">{displayText(service.id,'service id unavailable')}</div></div><div className="vv-render-value"><div className="vv-eyebrow">Service state</div><strong>{displayText(serviceState)}</strong><div className="mt-1 text-[10px] text-[var(--vv-muted)]">{displayText(service.type,'Render service')}</div></div><div className="vv-render-value"><div className="vv-eyebrow">Latest deployment</div><strong>{STATUS_LABELS[String(displayText(deploy.status,'')).toLowerCase()]||displayText(deploy.status)}</strong><div className="mt-1 text-[10px] text-[var(--vv-muted)]">{displayText(deploy.id)}</div></div><div className="vv-render-value"><div className="vv-eyebrow">Runtime URL</div><strong className="break-all">{displayText(service.url)}</strong><div className="mt-1 text-[10px] text-[var(--vv-muted)]">Polled from server-side Render API bridge</div></div></div></>}</section><section className="vv-panel mt-4"><div className="vv-panel-head"><h2>Recent Render Logs</h2><span>10 minute window</span></div>{logsQuery.isPending?<p className="vv-copy">Loading Render logs…</p>:logsQuery.isError?<div className="vv-status-row error"><Server size={15}/><span>{displayText(logsQuery.error?.message,'Render logs unavailable.')}</span></div>:logRecords.length?<div className="vv-log-stream">{logRecords.slice(0,60).map((record,index)=>{const message=displayText(record?.message??record?.text??record?.event,'Render log event');const rawTime=record?.timestamp??record?.time;const time=rawTime?new Date(rawTime).toLocaleString():'—';return <div className="vv-log-row" key={`${String(rawTime||'')}-${index}`}><div><Terminal size={15}/></div><div className="vv-log-main"><div><strong className="text-white/75">{message}</strong><span className="vv-log-time">{time}</span></div></div></div>})}</div>:<p className="vv-copy">No recent Render log records were returned.</p>}</section></div>
}
function LogPanel({ query }) { const records=query.data?.payload?.events||query.data?.events||[]; return <div><PageTitle eyebrow="OBSERVE" title="Live Logs" action={<Button variant="secondary" onClick={()=>query.refetch()}><RefreshCw size={14}/> Refresh</Button>}/><section className="vv-panel"><div className="vv-log-banner"><span className="vv-live-dot"/> Live diagnostic stream · polling every 2.5 seconds while this panel is open</div>{query.isPending?<p className="vv-copy">Loading live diagnostics…</p>:query.isError?<div className="vv-status-row error"><XCircle size={16}/><span>{query.error?.message||'Unable to load diagnostic events.'}</span></div>:records.length?<div className="vv-log-stream">{records.map((record,index)=><div className="vv-log-row" key={`${record.timestamp}-${record.event}-${index}`}><div className="text-white/45">{record.event?.includes('error')||record.event?.includes('failed')?<XCircle size={16}/>:record.event?.includes('completed')||record.event?.includes('uploaded')?<CheckCircle2 size={16}/>:<Activity size={16}/>}</div><div className="vv-log-main"><div><strong className="text-white/75">{record.event||'diagnostic event'}</strong><span className="vv-log-time">{record.timestamp?new Date(record.timestamp).toLocaleString():'—'}</span></div><p>{record.error_message||record.detail||record.reason||record.stage||'Lifecycle event recorded.'}</p><div className="vv-error-meta"><span>Request {record.request_id||'—'}</span>{record.status_code!=null&&<span>HTTP {record.status_code}</span>}{record.duration_ms!=null&&<span>{record.duration_ms} ms</span>}{record.stage&&<span>Stage {record.stage}</span>}</div></div></div>)}</div>:<p className="vv-copy">No diagnostic events were returned for the selected window.</p>}</section></div> }
function ErrorPanel({ query }) { const records=query.data?.payload?.events||query.data?.events||[]; return <div><PageTitle eyebrow="OBSERVE" title="Error Reports" action={<Button variant="secondary" onClick={()=>query.refetch()}><RefreshCw size={14}/> Refresh</Button>}/><section className="vv-panel">{query.isPending?<p className="vv-copy">Loading persisted errors…</p>:query.isError?<div className="vv-status-row error"><XCircle size={16}/><span>{query.error?.message||'Unable to load persisted errors.'}</span></div>:records.length?<div className="vv-log-stream">{records.map((record,index)=><div className="vv-log-row" key={`${record.timestamp}-${record.request_id}-${index}`}><div className="text-red-300/80"><XCircle size={17}/></div><div className="vv-log-main"><div><strong className="text-red-100/80">{record.event||'error'}</strong><span className="vv-log-time">{record.timestamp?new Date(record.timestamp).toLocaleString():'—'}</span></div><p>{record.error_message||record.detail||record.reason||'No sanitized error message was recorded.'}</p><div className="vv-error-meta"><span>Request {record.request_id||'—'}</span>{record.error_type&&<span>{record.error_type}</span>}{record.status_code!=null&&<span>HTTP {record.status_code}</span>}{record.source_revision&&<span>Revision {record.source_revision.slice(0,12)}</span>}</div></div></div>)}</div>:<p className="vv-copy">No persisted errors were returned for the selected window.</p>}</section></div> }
function Audits({ notify }) { return <div><PageTitle eyebrow="ASSURANCE" title="Structured Audits" action={<ExportActions value={AUDIT_REPORTS} filename="voxvector-audits.json" label="Audit index" notify={notify}/>}/><div className="vv-audit-intro">Recent evidence-based audits of the current VoxVector system. Findings distinguish observed facts from required production verification. Each audit can be copied or downloaded from the canonical console.</div><div className="space-y-4">{AUDIT_REPORTS.map(report=><section className="vv-panel" key={report.id}><div className="vv-panel-head"><div><div className="vv-eyebrow">{report.date}</div><h2>{report.title}</h2></div><div className="flex flex-wrap items-center gap-2"><span>{report.status}</span><ExportActions value={report} filename={`${report.id}.json`} label={report.title} notify={notify}/></div></div><p className="vv-copy">{report.summary}</p><div className="vv-audit-tags">{report.scope.map(item=><span key={item}>{item}</span>)}</div><div className="mt-5 space-y-2">{report.findings.map((finding,index)=><div className="vv-audit-finding" key={index}><div className={`vv-audit-severity ${finding.severity}`}>{finding.severity}</div><div><strong>{finding.title}</strong><p>{finding.detail}</p></div></div>)}</div><div className="mt-5 grid gap-4 lg:grid-cols-2"><div><div className="vv-eyebrow">Next Verification</div><ul className="vv-audit-list">{report.next.map(item=><li key={item}>{item}</li>)}</ul></div><div><div className="vv-eyebrow">Evidence</div><ul className="vv-audit-list">{report.evidence.map(item=><li key={item}><code>{item}</code></li>)}</ul></div></div></section>)}</div></div> }
function Profile({ session,signOut,avatar }) { const user=session?.user||{}, meta=user.user_metadata||{}; return <div><PageTitle eyebrow="ACCOUNT" title="Developer Profile"/><section className="vv-panel"><div className="flex flex-wrap items-center gap-4">{avatar}<div className="min-w-0"><div className="truncate text-lg font-semibold">{meta.full_name||meta.name||user.email?.split('@')[0]||'Developer'}</div><div className="truncate text-sm text-[var(--vv-muted)]">{user.email||'Authenticated developer'}</div><div className="mt-1 text-[11px] text-[var(--vv-muted)]">Developer role is enforced by Supabase application metadata.</div></div></div><div className="mt-5 flex flex-wrap gap-2"><Button variant="secondary" onClick={()=>signOut()}><LogOut size={15}/> Sign out</Button></div></section></div> }
function Data({ label,value }) { return <div><div className="vv-eyebrow">{label}</div><div className="mt-1 text-sm break-words">{value||'—'}</div></div> }
function DocLink({ title,href,detail }) { return <a href={href} target="_blank" rel="noreferrer" className="border border-[var(--vv-border)] p-4 no-underline transition hover:border-[var(--vv-border-strong)]"><div className="font-medium">{title}</div><div className="mt-1 text-xs text-[var(--vv-muted)]">{detail}</div></a> }
function Docs() { return <div><PageTitle eyebrow="SOURCE" title="Methodology & Documentation"/><div className="grid gap-3 md:grid-cols-2">{Object.entries(DOCS).map(([key,href])=><DocLink key={key} title={key} href={href} detail={href}/>)}</div></div> }
function MvpBoard({ checks, setChecks, percent, complete, total }) { const [open,setOpen]=useState(()=>new Set(['P0','P1'])); const allOpen=open.size===phases.length; const togglePhase=id=>setOpen(current=>{const next=new Set(current); if(next.has(id)) next.delete(id); else next.add(id); return next}); const toggle=id=>setChecks(current=>({...current,[id]:!current[id]})); return <div><PageTitle eyebrow="DELIVERY" title="Fastest Path to MVP" action={<div className="flex gap-2"><Button variant="secondary" onClick={()=>setOpen(allOpen ? new Set() : new Set(phases.map(p => p.id)))}>{allOpen?'Collapse All':'Expand All'}</Button><Button variant="secondary" onClick={()=>setChecks({})}>Reset Checks</Button></div>}/><section className="vv-panel mb-4"><div className="vv-eyebrow">MVP Execution Board</div><div className="mt-1 text-2xl font-semibold">{percent}% complete</div><p className="vv-copy mt-1">{complete} of {total} engineering tasks checked</p></section><div className="space-y-2">{phases.map(phase=>{const done=phase.tasks.filter(([id])=>checks[id]).length,isOpen=open.has(phase.id); return <section className="vv-panel" key={phase.id}><button className="flex w-full items-center gap-3 text-left" onClick={()=>togglePhase(phase.id)} aria-expanded={isOpen}>{isOpen?<ChevronDown size={17}/>:<ChevronRight size={17}/>}<span className="vv-eyebrow">{phase.id}</span><strong className="text-sm">{phase.title}</strong><span className="ml-auto text-xs text-[var(--vv-muted)]">{done}/{phase.tasks.length}</span></button>{isOpen&&<div className="mt-4 space-y-1">{phase.tasks.map(([id,label,owner])=><button key={id} onClick={()=>toggle(id)} className="vv-status-row w-full text-left"><span className="check-format">{checks[id]?<CircleCheck size={16}/>:<Circle size={16}/>}</span><span className={checks[id]?'line-through opacity-60':''}>{label}</span><span className="ml-auto text-[10px] uppercase tracking-wider text-[var(--vv-muted)]">{owner}</span></button>)}</div>}<p className="vv-copy mt-3">{phase.detail}</p></section>})}</div></div> }